head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.v_up_schdl_adm_itm_tp_cd = "";
scwin.v_up_schdl_adm_itm_tp_nm = "";
scwin.v_ldMktTpCd = "";
scwin.txb_date = "";
scwin.v_cdNm = "";

// 화면 리사이징

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.v_up_schdl_adm_itm_tp_cd = $c.frame.path("../").scwin.v_up_schdl_adm_itm_tp_cd;
        scwin.v_up_schdl_adm_itm_tp_nm = $c.frame.path("../").scwin.v_up_schdl_adm_itm_tp_nm;
        scwin.v_ldMktTpCd = $c.frame.path("../").scwin.v_ldMktTpCd;
        if (scwin.v_ldMktTpCd === "1") {
            txt_ld_mkt_tp_nm.setValue("유가");
        } else if (scwin.v_ldMktTpCd === "2") {
            txt_ld_mkt_tp_nm.setValue("코스닥");
        } else if (scwin.v_ldMktTpCd === "6") {
            txt_ld_mkt_tp_nm.setValue("코넥스");
        } else if (scwin.v_ldMktTpCd === "4") {
            txt_ld_mkt_tp_nm.setValue("채권");
        }
        txt_up_schdl_adm_itm_tp_cd.setValue(scwin.v_up_schdl_adm_itm_tp_cd);
        txt_up_schdl_adm_itm_tp_nm.setValue(scwin.v_up_schdl_adm_itm_tp_nm);
        txt_up_schdl_adm_itm_tp_cd.style.display = "none";
        url += "&LD_MKT_TP_CD=" + scwin.v_ldMktTpCd;
        url += "&SCREN_ID=" + 'ULDSTF39204.xml';
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_MxDataSet_schdl_tp_cd",
            action : "/DisclosureSchedule.do",
            ref : "",
            target : "MxDataSet_schdl_tp_cd=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_MxDataSet",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "MxDataSet=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const toDay = '';
        const clientnow = new Date();

        /* 오늘 날짜를 구한다 */
        const curYear = clientnow.getYear();
        let curMonth = (clientnow.getMonth()) + 1;
        let curDay = clientnow.getDate();
        if (curMonth <= 9) {
            curMonth = "0" + curMonth;
        }
        if (curDay <= 9) {
            curDay = "0" + curDay;
        }
        scwin.txb_date = curYear + "" + curMonth + "" + curDay;

        // var url = "/bzchklist.do?method=searchBzChkList&inputMessageId=bzchklist&outputMessageId=bzchklist&BAS_DD="+txb_date+"&CHK_BZ_TP_CD=00" +"&SCREN_ID="  + vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        // MxDataSet_dep_cd.DataID =  encodeURI(url);
        // MxDataSet_dep_cd.reset();

        checkbox_1.setValue(1);
        cmb_dep_cd.style.display = "none";
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39204.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39204.btn_save_onclick" });
    }
};

/**
 * @method
 * @name checkbox_1_onclick
 * @description checkbox_1 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.checkbox_1_onclick = function() {
    try {
        if (cmb_dep_cd.style.display === "") {
            cmb_dep_cd.style.display = "none";
        } else {
            cmb_dep_cd.style.display = "";
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39204.checkbox_1_onclick" });
    }
};

/**
 * @method
 * @name MxLogicalTr_OnSuccess
 * @description Mx Logical Tr On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MxLogicalTr_OnSuccess = async function() {
    try {
        await $c.win.alert('저장이 완료되었습니다.');
        $c.frame.path("../").fn_ReSearch(scwin.v_cdNm);
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39204.MxLogicalTr_OnSuccess" });
    }
};

/**
 * @method
 * @name MxLogicalTr_OnFail
 * @description Mx Logical Tr On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MxLogicalTr_OnFail = async function() {
    try {
        await $c.win.alert('저장에 실패했습니다.');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39204.MxLogicalTr_OnFail" });
    }
};

/**
 * @method
 * @name MxDataSet_OnLoadCompleted
 * @description MxDataSet 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_OnLoadCompleted = function(rowcount) {
    try {
        MxDataSet.insertRow();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39204.MxDataSet_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name MxDataSet_schdl_tp_cd_OnLoadError
 * @description MxDataSet_schdl_tp_cd 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MxDataSet_schdl_tp_cd_OnLoadError = async function() {
    try {
        await $c.win.alert(MxDataSet_schdl_tp_cd);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39204.MxDataSet_schdl_tp_cd_OnLoadError" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    MxDataSet.setCellData(1, "UP_SCHDL_ADM_ITM_TP_CD", scwin.v_up_schdl_adm_itm_tp_cd);
    MxDataSet.setCellData(1, "LD_MKT_TP_CD", scwin.v_ldMktTpCd);
    MxDataSet.setCellData(1, "SCHDL_ADM_ITM_TP_CD", $c.cp.valueOfIndex(cmb_schdl_adm_itm_tp_cd, "SCHDL_ADM_ITM_TP_CD", cmb_schdl_adm_itm_tp_cd.getSelectedIndex()));
    MxDataSet.setCellData(1, "CD_NM", txt_cd_nm.getValue());
    scwin.v_cdNm = txt_cd_nm.getValue();
    if (checkbox_1.checked === true) {
        MxDataSet.setCellData(1, "DEP_CD", "0");
    } else {
        MxDataSet.setCellData(1, "DEP_CD", $c.cp.valueOfIndex(cmb_dep_cd, "value", cmb_dep_cd.getSelectedIndex()));
    }
    if (!await scwin.saveChk()) {
        return;
    }
    if (!confirm("저장하시겠습니까?")) {
        return;
    }
    MxLogicalTr.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_MxLogicalTr",
        action : "/DisclosureSchedule.do",
        ref : "MxDataSet",
        target : "MxLogicalTr=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name saveChk
 * @description 상위일정관리항목유형코드
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveChk = async function() {
    // 상위일정관리항목유형코드
    if (txt_cd_nm.getValue() === "") {
        const msg = $c.stf.getMessageParam("MSG-A005", "코드명");
        await $c.win.alert(msg);
        txt_cd_nm.focus();
        return false;
    }
    return true;
};
